```ts
#!/usr/bin/env bun
/**
 * Smoke-rig stand-in for a phase worker that acknowledges every prompt and never starts a turn
 * (LEGION-93). Runs as an `omp_launch_prefix` entry between `legion worker-shim` and OMP:
 *
 *   SMOKE_OMP_LAUNCH_PREFIX="secrets … -- $(command -v bun) $PWD/scripts/smoke/swallow-prompts.ts --role planner --"
 *
 * For a pane whose LEGION_ROLE is `--role` (and LEGION_ISSUE is `--issue`, when given) running
 * `--mode rpc`, it answers each RPC `prompt` command itself with `{success:true}` and never forwards
 * it to OMP — OMP idles, emits no `agent_start`, and answers the forwarded `get_state` with
 * `isStreaming:false` — while every other frame in both directions is forwarded verbatim (the real
 * shim, OMP, and the plugin's boot handshake all run for real). Any other pane, and the daemon's two
 * boot probes, run the wrapped command with inherited stdio, untouched. Stdin EOF (the shim's
 * `shutdown`) closes OMP's stdin; the exit code is OMP's.
 */
const argv = process.argv.slice(2);
let role: string | undefined;
let issue: string | undefined;
while (argv.length > 0 && argv[0] !== "--") {
  const flag = argv.shift();
  if (flag === "--role") role = argv.shift();
  else if (flag === "--issue") issue = argv.shift();
  else {
    console.error(`[swallow-prompts] unknown flag ${flag}`);
    process.exit(2);
  }
}
if (argv.shift() !== "--" || argv.length === 0 || !role) {
  console.error("usage: swallow-prompts.ts --role <role> [--issue <key>] -- <command…>");
  process.exit(2);
}
const modeIndex = argv.indexOf("--mode");
const intercept =
  process.env.LEGION_ROLE === role &&
  (issue === undefined || process.env.LEGION_ISSUE === issue) &&
  modeIndex !== -1 &&
  argv[modeIndex + 1] === "rpc";

if (!intercept) {
  const passthrough = Bun.spawn(argv, { stdin: "inherit", stdout: "inherit", stderr: "inherit" });
  process.exit(await passthrough.exited);
}

console.error(
  `[swallow-prompts] swallowing every prompt for ${process.env.LEGION_ROLE} on ${process.env.LEGION_ISSUE}`
);
const child = Bun.spawn(argv, { stdin: "pipe", stdout: "pipe", stderr: "inherit" });
const out = Bun.stdout.writer();

// OMP -> shim: verbatim.
void (async () => {
  for await (const chunk of child.stdout) {
    out.write(chunk);
    out.flush();
  }
})();

// shim -> OMP: answer `prompt` here, forward everything else; EOF closes OMP's stdin.
const decoder = new TextDecoder();
let buffered = "";
for await (const chunk of Bun.stdin.stream()) {
  buffered += decoder.decode(chunk, { stream: true });
  let newline = buffered.indexOf("\n");
  while (newline !== -1) {
    const line = buffered.slice(0, newline);
    buffered = buffered.slice(newline + 1);
    newline = buffered.indexOf("\n");
    if (line.length === 0) continue;
    let frame: unknown;
    try {
      frame = JSON.parse(line);
    } catch {
      frame = undefined;
    }
    if (typeof frame === "object" && frame !== null && (frame as { type?: unknown }).type === "prompt") {
      const id = (frame as { id?: unknown }).id;
      console.error(`[swallow-prompts] swallowed prompt ${String(id)}`);
      out.write(`${JSON.stringify({ id, type: "response", command: "prompt", success: true })}\n`);
      out.flush();
      continue;
    }
    child.stdin.write(`${line}\n`);
    child.stdin.flush();
  }
}
child.stdin.end();
process.exit(await child.exited);
